#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

// 测试缓冲区越界读取 - 长度小于4字节但函数尝试读取4字节头部信息
void test_out_of_bounds_read_small_buffer() {
    unsigned char small_buffer[] = {0x01, 0x00}; // 只有2字节，但函数可能尝试读取4字节
    uint16_t page_count;

    printf("Testing out-of-bounds read with 2-byte buffer...\n");
    int result = parse_document_header(small_buffer, 2, &page_count);
    printf("Result: %d\n", result);
}

// 测试边界情况 - 长度为3字节
void test_out_of_bounds_read_3_bytes() {
    unsigned char buffer_3_bytes[] = {0x01, 0x00, 0x10}; // 3字节，不够读取完整的4字节头部
    uint16_t page_count;

    printf("Testing out-of-bounds read with 3-byte buffer...\n");
    int result = parse_document_header(buffer_3_bytes, 3, &page_count);
    printf("Result: %d\n", result);
}

// 测试长度为1字节的情况
void test_out_of_bounds_read_1_byte() {
    unsigned char buffer_1_byte[] = {0x01}; // 1字节
    uint16_t page_count;

    printf("Testing out-of-bounds read with 1-byte buffer...\n");
    int result = parse_document_header(buffer_1_byte, 1, &page_count);
    printf("Result: %d\n", result);
}

// 测试长度为0的情况
void test_out_of_bounds_read_0_bytes() {
    unsigned char* null_buffer = NULL;
    uint16_t page_count;

    printf("Testing out-of-bounds read with 0-byte buffer (NULL)...\n");
    int result = parse_document_header(null_buffer, 0, &page_count);
    printf("Result: %d\n", result);
}

int main() {
    printf("Running security tests for parse_document_header...\n");
    printf("These tests are designed to trigger out-of-bounds read vulnerabilities (CWE-125)\n");

    test_out_of_bounds_read_small_buffer();
    test_out_of_bounds_read_3_bytes();
    test_out_of_bounds_read_1_byte();
    test_out_of_bounds_read_0_bytes();

    printf("Security tests completed.\n");
    return 0;
}

genhints.fun_test:
#include "document_parser.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <assert.h>

// 文档头部格式：版本号(2字节) + 页数(2字节) + 其他头部信息
// 模拟正常文档头部数据
unsigned char normal_doc_header[] = {
    0x01, 0x00,  // 版本号 1.0
    0x10, 0x00   // 页数 16 (小端序)
};

// 测试正常功能
void test_normal_case() {
    uint16_t page_count;
    int result = parse_document_header(normal_doc_header, sizeof(normal_doc_header), &page_count);

    if (result == 0 && page_count == 16) {
        printf("PASS: Normal case test\n");
    } else {
        printf("FAIL: Normal case test - result: %d, page_count: %d\n", result, page_count);
    }
}

// 测试边界条件 - 最小有效文档长度
void test_min_length() {
    unsigned char min_header[] = {0x01, 0x00, 0x10, 0x00}; // 4字节，刚好包含版本和页数
    uint16_t page_count;
    int result = parse_document_header(min_header, sizeof(min_header), &page_count);

    if (result == 0 && page_count == 16) {
        printf("PASS: Minimum length test\n");
    } else {
        printf("FAIL: Minimum length test - result: %d, page_count: %d\n", result, page_count);
    }
}

// 测试大页数
void test_large_page_count() {
    unsigned char header_with_large_page[] = {
        0x01, 0x00,  // 版本号
        0xFF, 0xFF   // 页数 65535 (最大uint16_t值)
    };
    uint16_t page_count;
    int result = parse_document_header(header_with_large_page, sizeof(header_with_large_page), &page_count);

    if (result == 0 && page_count == 65535) {
        printf("PASS: Large page count test\n");
    } else {
        printf("FAIL: Large page count test - result: %d, page_count: %d\n", result, page_count);
    }
}

// 测试空指针情况
void test_null_pointer() {
    int result = parse_document_header(NULL, 4, NULL);
    if (result != 0) {
        printf("PASS: Null pointer test\n");
    } else {
        printf("FAIL: Null pointer test - expected non-zero return\n");
    }
}

// 测试长度为0
void test_zero_length() {
    uint16_t page_count;
    int result = parse_document_header(normal_doc_header, 0, &page_count);
    if (result != 0) {
        printf("PASS: Zero length test\n");
    } else {
        printf("FAIL: Zero length test - expected non-zero return\n");
    }
}

int main() {
    printf("Running functional tests for parse_document_header...\n");

    test_normal_case();
    test_min_length();
    test_large_page_count();
    test_null_pointer();
    test_zero_length();

    printf("Functional tests completed.\n");
    return 0;
}

